            text = prefix + text.slice(prefix.length).padStart(Math.max(0, width - prefix.length), "0");
          } else text = text.padStart(width, " ");
          await output(context, text);
        }
        if (argument === before) break;
      } while (argument < args.length && !stopped);
      return { exitCode };
    }),
  ];
}

