import { Interpreter } from "./interpreter.js";
import { parse } from "./parser.js";

interface Options {
  raw: boolean;
  rawInput: boolean;
  joinOutput: boolean;
  compact: boolean;
  slurp: boolean;
  nullInput: boolean;
  exitStatus: boolean;
  source: string | undefined;
  programFile: string | undefined;
  files: string[];
  variables: Map<string, Json>;
